package android.util; import java.util.*; public class SparseArray<T> { final TreeMap<Integer,T> m=new TreeMap<>(); public SparseArray(){} public SparseArray(int n){} public T get(int k){return m.get(k);} public T get(int k,T d){return m.getOrDefault(k,d);} public void put(int k,T v){m.put(k,v);} public void append(int k,T v){put(k,v);} public void clear(){m.clear();} public int size(){return m.size();} public int keyAt(int i){return new ArrayList<>(m.keySet()).get(i);} public T valueAt(int i){return m.get(keyAt(i));} public int indexOfKey(int k){return new ArrayList<>(m.keySet()).indexOf(k);} public void remove(int k){m.remove(k);} public void delete(int k){m.remove(k);} }
